selector_to_html = {"a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.regen.channel_construction\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.channel_construction<a class=\"headerlink\" href=\"#module-pyskyfire.regen.channel_construction\" title=\"Link to this heading\">\u00b6</a></h1><p>Resolve nominal paths into physical section anchors, arcs and centroids.</p><p>The normal section is projected locally onto an engine-axis-normal plane to\nallocate gas area. This is exact for prismatic sections; a curved CAD loft is\nan approximation to the sequence of these local sections.</p>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.regen.channel_construction.ConstructionArc\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.channel_construction.ConstructionArc\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.channel_construction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ConstructionArc</span></span></dt><dd></dd>", "a[href=\"ChannelConstruction.html#pyskyfire.regen.channel_construction.ChannelConstruction\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.channel_construction.ChannelConstruction\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.channel_construction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ChannelConstruction</span></span></dt><dd><p>One circuit\u2019s resolved section geometry along a nominal winding.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">planes</span></code> are what the section boundary is drawn in \u2013 transverse for a\nsquared section, flow-normal for a rounded one \u2013 while <code class=\"docutils literal notranslate\"><span class=\"pre\">flow_planes</span></code> are\nalways flow-normal and are what the centroid is measured in. <code class=\"docutils literal notranslate\"><span class=\"pre\">profiles</span></code>\ncarries the resolved dimensions, including the base-point path the section\nis anchored on, and <code class=\"docutils literal notranslate\"><span class=\"pre\">gas_area</span></code> the combustion-gas area each channel\u2019s\nsector keeps.</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.regen.channel_construction.build_channel_construction\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.channel_construction.build_channel_construction\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.channel_construction.</span></span><span class=\"sig-name descname\"><span class=\"pre\">build_channel_construction</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuit</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">reference_path</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Build sections from the ideal-contour winding, including rotated seeds.</p><p>Every angular sector receives its share of the target gas area. Rounded\nlobes are tangent to that sector in the locally projected geometry; liners\nextend the gas-facing arc inward. No translation follows lobe sizing.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
